import type { Choice, Mission } from "../../types";

/**
 * M11 — The Co-Creation Studio.
 * All people, organisations and the publishing policy are fictional. Drafts are authored, not generated.
 */

const POLICY =
  "The Commons' publishing policy: (1) Say when AI was used, if an image was generated by AI or if AI-written text is published largely unchanged. (2) Use photos of people only if each of them has signed a consent form, and use only images the Commons owns or has permission to use. (3) A quotation from a published work that is longer than one sentence needs permission. (4) A named member of staff approves everything published, and answers for it.";

const responsibilityQuestion = "You use AI to help make a poster. Who is responsible for what the final poster says and shows?";
const responsibilityChoices: Choice[] = [
  { id: "a", label: "The company behind the AI tool, for the parts the AI generated.", verdict: "weaker", explanation: "The company didn't choose to publish the poster. Whoever publishes it answers for it, whichever tool helped." },
  { id: "b", label: "You, and whoever approves it, whatever the AI contributed.", verdict: "correct", explanation: "AI can suggest, but people choose what is published. That is why recording who contributed what matters: it shows what you checked and decided." },
  { id: "c", label: "You and the AI share the responsibility equally between you.", verdict: "weaker", explanation: "A tool can't answer to anyone for what it contributed. The responsibility for the final choices is yours." },
];

